// Generate llms.txt (page map) and llms-full.txt (contract full text).
//
// llms-full.txt is one file, kept under 1 MB by emitting the tool contract
// (overview, arguments, API routes, notes) rather than a verbatim dump.
// Examples stay on each HTML page.
//
// Canonical output: docs/llms/. Mirrored into docs/static/ so start/build serve:
//   /llms.txt
//   /llms/llms.txt
//   /llms/llms-full.txt
//
// Regenerated by docs/scripts/generateSiteData.mjs. Do not edit by hand.
//
// Dependency-free ESM. Node >= 18.

import { existsSync, mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

import { readJson, rewriteExtLinks, substituteVars } from './lib/docsMarkdown.mjs';
import { desktopContractPreamble, toContractMarkdown } from './lib/llmsContract.mjs';
import { buildLlmsSections, flattenPages } from './lib/llmsPages.mjs';
import { projectReleaseNotesMarkdown } from './lib/projectReleaseNotes.mjs';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const DEFAULT_DOCS_DIR = join(SCRIPT_DIR, '..');

export const SITE_TITLE = 'Tableau MCP';
export const SITE_SLUG = 'tableau-mcp';
export const INDEX_BASENAME = 'llms.txt';
export const FULL_BASENAME = 'llms-full.txt';

const SITE_SUMMARY = "Tableau's official MCP Server. Helping Agents see and understand data.";

const OFFICIAL_ORIGIN = 'https://tableau.github.io';
const DEFAULT_BASE_PATH = '/tableau-mcp';

const LEFTOVER_STATIC_ROOT = ['tableau-mcp-llms.txt'];

export function siteOrigin(env = process.env) {
  return (env.GITHUB_ORIGIN ?? OFFICIAL_ORIGIN).replace(/\/$/, '');
}

export function siteBasePath(env = process.env) {
  return (env.GITHUB_BASE_PATH ?? DEFAULT_BASE_PATH).replace(/\/$/, '');
}

export function absolutePageUrl(docPath, env = process.env) {
  return `${siteOrigin(env)}${siteBasePath(env)}${docPath}`;
}

export function absoluteLlmsUrl(fileName, env = process.env) {
  return `${siteOrigin(env)}${siteBasePath(env)}/llms/${fileName}`;
}

function clearGeneratedDir(dir) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    rmSync(join(dir, name), { recursive: true, force: true });
  }
}

function unlinkIfExists(abs) {
  if (existsSync(abs)) rmSync(abs, { force: true });
}

function renderLlmsTxt(sections, env) {
  const fullUrl = absoluteLlmsUrl(FULL_BASENAME, env);
  const lines = [`# ${SITE_TITLE}`, '', `> ${SITE_SUMMARY}`, ''];
  lines.push(
    'This file is the map of every published page. For contract full text',
    `(arguments, API routes, notes — under 1 MB) fetch [${FULL_BASENAME}](${fullUrl}).`,
    'Examples stay on each HTML page.',
    '',
  );
  for (const section of sections) {
    if (!section.heading && !section.pages.length) continue;
    if (section.heading) {
      const mark = section.level === 3 ? '###' : '##';
      lines.push(`${mark} ${section.heading}`, '');
    }
    if (section.description) {
      const desc = rewriteExtLinks(substituteVars(section.description), env)
        .replace(/\s+/g, ' ')
        .trim();
      if (desc) lines.push(`> ${desc}`, '');
    }
    for (const page of section.pages) {
      const url = absolutePageUrl(page.docPath, env);
      const suffix = page.summary ? `: ${page.summary}` : '';
      lines.push(`- [${page.title}](${url})${suffix}`);
    }
    if (section.pages.length) lines.push('');
  }
  lines.push(
    '## Optional',
    '',
    `- [${FULL_BASENAME}](${fullUrl}): contract full text of every published page`,
    '- [GitHub repository](https://github.com/tableau/tableau-mcp): source for Tableau MCP',
    '- [Hosted Tableau MCP](https://mcp.tableau.com): managed MCP endpoint on Tableau Cloud',
    '- [Model Context Protocol](https://modelcontextprotocol.io/introduction): the protocol this server implements',
    '',
  );
  return lines.join('\n').replace(/\n{3,}/g, '\n\n');
}

function bodyWithoutRedundantTitle(page) {
  const body = page.body.trim();
  const escaped = page.title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return body.replace(new RegExp(`^#\\s+${escaped}\\s*\\n+`), '');
}

function renderLlmsFull(pages, env, docsDir) {
  const releaseNotesPath = join(docsDir, 'docs/release-notes.mdx');
  const entries = readJson(join(docsDir, 'src/data/releaseNotes.json'), []);
  const siteContent = readJson(join(docsDir, 'src/data/releaseSiteContent.json'), []);
  const chunks = [
    `# ${SITE_TITLE}`,
    '',
    `> ${SITE_SUMMARY}`,
    '',
    `Contract text of ${pages.length} published pages (arguments, API routes, notes).`,
    'Examples stay on each page URL. Index: ' + absoluteLlmsUrl(INDEX_BASENAME, env),
    '',
    desktopContractPreamble(),
  ];
  for (const page of pages) {
    const url = absolutePageUrl(page.docPath, env);
    chunks.push('---', '', `# ${page.title}`, '', `Source: ${url}`, '');
    if (page.abs === releaseNotesPath || page.rel === 'release-notes.mdx') {
      chunks.push(projectReleaseNotesMarkdown(entries, siteContent, url).trimEnd(), '');
    } else {
      chunks.push(toContractMarkdown(bodyWithoutRedundantTitle(page)), '');
    }
  }
  return `${chunks.join('\n').trim()}\n`;
}

export function generateLlmsTxt({
  docsDir = DEFAULT_DOCS_DIR,
  outDir = join(docsDir, 'llms'),
  staticDir = join(docsDir, 'static'),
  env = process.env,
} = {}) {
  const docsRoot = join(docsDir, 'docs');
  const sections = buildLlmsSections(docsRoot, env);
  const pages = flattenPages(sections);
  if (pages.length === 0) {
    throw new Error('generateLlmsTxt: no published pages found');
  }
  const seenTitles = new Map();
  for (const p of pages) {
    if (seenTitles.has(p.title)) {
      throw new Error(
        `generateLlmsTxt: duplicate title "${p.title}" (${seenTitles.get(p.title)} and ${p.docPath})`,
      );
    }
    seenTitles.set(p.title, p.docPath);
  }
  const llmsTxt = renderLlmsTxt(sections, env);
  const llmsFull = renderLlmsFull(pages, env, docsDir);

  clearGeneratedDir(outDir);
  mkdirSync(outDir, { recursive: true });
  const llmsTxtPath = join(outDir, INDEX_BASENAME);
  const llmsFullPath = join(outDir, FULL_BASENAME);
  writeFileSync(llmsTxtPath, llmsTxt);
  writeFileSync(llmsFullPath, llmsFull);

  if (staticDir) {
    const staticLlmsDir = join(staticDir, 'llms');
    clearGeneratedDir(staticLlmsDir);
    mkdirSync(staticLlmsDir, { recursive: true });
    for (const leftover of LEFTOVER_STATIC_ROOT) unlinkIfExists(join(staticDir, leftover));
    writeFileSync(join(staticDir, INDEX_BASENAME), llmsTxt);
    writeFileSync(join(staticLlmsDir, INDEX_BASENAME), llmsTxt);
    writeFileSync(join(staticLlmsDir, FULL_BASENAME), llmsFull);
  }

  return {
    pageCount: pages.length,
    llmsTxtPath,
    llmsFullPath,
    llmsTxtBytes: Buffer.byteLength(llmsTxt),
    llmsFullBytes: Buffer.byteLength(llmsFull),
  };
}

function isMain() {
  return Boolean(process.argv[1] && process.argv[1].endsWith('generateLlmsTxt.mjs'));
}

if (isMain()) {
  const result = generateLlmsTxt();
  const docsDir = DEFAULT_DOCS_DIR;
  console.log(
    `generateLlmsTxt: wrote ${result.pageCount} pages to ` +
      `${relative(docsDir, dirname(result.llmsTxtPath))} ` +
      `(index ${result.llmsTxtBytes} bytes, full ${result.llmsFullBytes} bytes)`,
  );
}
